"use client";

/**
 * Board sounds, from public/sounds (generated by scripts/make-sounds.py).
 *
 * Decoded once into Web Audio buffers rather than played through <audio>
 * elements: stepping quickly through a game fires a sound per move, and an
 * <audio> element restarted that fast clips or lags behind the board.
 */
export type SoundKind = "move" | "capture" | "castle" | "check" | "end";

const KINDS: SoundKind[] = ["move", "capture", "castle", "check", "end"];

let context: AudioContext | null = null;
let buffers: Promise<Partial<Record<SoundKind, AudioBuffer>>> | null = null;

function load(ctx: AudioContext) {
  buffers ??= Promise.all(
    KINDS.map(async (kind) => {
      try {
        const data = await (await fetch(`/sounds/${kind}.wav`)).arrayBuffer();
        return [kind, await ctx.decodeAudioData(data)] as const;
      } catch {
        return [kind, undefined] as const;
      }
    }),
  ).then((entries) => Object.fromEntries(entries.filter(([, b]) => b)));
  return buffers;
}

/** The sound a move makes, from its SAN: "O-O", "exd5", "Qh5+", "Qxf7#". */
export function soundFor(san: string, isLastMoveOfFinishedGame = false): SoundKind {
  if (san.endsWith("#") || isLastMoveOfFinishedGame) return "end";
  if (san.endsWith("+")) return "check";
  if (san.startsWith("O-O")) return "castle";
  if (san.includes("x")) return "capture";
  return "move";
}

export async function playSound(kind: SoundKind) {
  if (typeof window === "undefined") return;
  try {
    context ??= new AudioContext();
    // Browsers start an AudioContext suspended until a user gesture; every
    // call here follows a click or a key press, which is what resumes it.
    if (context.state === "suspended") await context.resume();
    const buffer = (await load(context))[kind];
    if (!buffer) return;
    const source = context.createBufferSource();
    source.buffer = buffer;
    source.connect(context.destination);
    source.start();
  } catch {
    // No audio on this device: the board works the same without it.
  }
}
